from django.core.management.base import BaseCommand
from common.models import FormFieldSetting


class Command(BaseCommand):
    help = "Initialize editable rent ledger wording without replacing existing edits."

    def handle(self,*args,**options):
        FormFieldSetting.objects.get_or_create(form_key="rent_ledger",field_key='ui',defaults={"label":'Rent ledger interface',"help_text":'',"option_labels":{'title': 'Rent Ledger', 'charges': 'Rent charges', 'receipts': 'Payment receipts', 'add_charge': 'Add rent charge', 'add_receipt': 'Record payment', 'back': 'Back to Lease 360', 'save': 'Save', 'cancel': 'Cancel', 'void': 'Void entry', 'voided': 'Entry voided.', 'saved': 'Rent entry saved.', 'credit_applied': 'Available credit applied to open rent charges.', 'apply_credit': 'Apply available credit', 'charged': 'Charges posted', 'received': 'Payments recorded', 'outstanding': 'Outstanding charges', 'overdue': 'Overdue rent', 'credit': 'Unallocated credit', 'period': 'Rent period', 'due': 'Due date', 'amount': 'Amount', 'applied': 'Applied', 'balance': 'Balance', 'date': 'Received date', 'method': 'Method', 'reference': 'Reference', 'status': 'Status', 'actions': 'Actions', 'empty': 'No entries yet.', 'posted': 'Posted', 'recorded': 'Recorded', 'void_status': 'Void', 'manual_help': 'This ledger records rent charges and payments already received. It does not collect money, send receipts, or synchronize bank or QuickBooks balances. Security deposits are separate.', 'charge_help': 'Confirm the rent period, due date, and amount before saving. The suggested amount uses currently effective lease terms. Confirm historical terms and any proration manually. No charges are backfilled automatically.', 'receipt_help': 'Record money already received. Payments apply to the oldest open rent charges on this lease; any remainder stays as unallocated credit. This is a rent-only allocation, not a legal priority rule for other fees.', 'void_help': 'Voiding preserves the entry and its audit history. Voiding a receipt restores the charges it paid. It does not refund money.', 'invalid_entry': 'This entry is not available for this action.', 'expired_form': 'This entry form expired. Open a new form and try again.', 'lease_not_active': 'New rent charges require an Active or Notice lease.', 'lease_not_receivable': 'Payments cannot be recorded against a Draft, Pending, or Cancelled lease.', 'invalid_charge': 'Enter a positive amount and a valid rent period.', 'invalid_receipt': 'Enter a positive payment amount and a received date that is not in the future.', 'invalid_account': 'Select an active receiving account that is not a credit card.', 'overlap': 'This rent period overlaps an existing posted charge. Review or void the existing entry before posting another.', 'reason_required': 'Enter a reason for voiding this entry.', 'charge_allocated': 'This charge has recorded payments applied. Void those receipts first if they were entered incorrectly.', 'ledger_link': 'Rent ledger', 'rent_outstanding': 'Rent charges outstanding', 'rent_credit': 'Unallocated rent credit', 'rent_overdue': 'Overdue rent', 'empty_ledger': 'No rent entries have been recorded yet. Open a lease rent ledger to enter charges and payments.', 'select_lease': 'Select a lease', 'lease': 'Property / Lease', 'no_collection': 'Record only payments already received; this does not initiate a transfer.'}})
        FormFieldSetting.objects.get_or_create(form_key="rent_ledger",field_key='period_start',defaults={"label":'Rent Period From',"help_text":'',"option_labels":{}})
        FormFieldSetting.objects.get_or_create(form_key="rent_ledger",field_key='period_end',defaults={"label":'Rent Period Until',"help_text":'',"option_labels":{}})
        FormFieldSetting.objects.get_or_create(form_key="rent_ledger",field_key='due_date',defaults={"label":'Payment Due Date',"help_text":'',"option_labels":{}})
        FormFieldSetting.objects.get_or_create(form_key="rent_ledger",field_key='amount',defaults={"label":'Amount ($)',"help_text":'',"option_labels":{}})
        FormFieldSetting.objects.get_or_create(form_key="rent_ledger",field_key='notes',defaults={"label":'Notes',"help_text":'',"option_labels":{}})
        FormFieldSetting.objects.get_or_create(form_key="rent_ledger",field_key='received_date',defaults={"label":'Payment Received On',"help_text":'',"option_labels":{}})
        FormFieldSetting.objects.get_or_create(form_key="rent_ledger",field_key='payment_method',defaults={"label":'Payment Method',"help_text":'',"option_labels":{'bank_transfer': 'Bank transfer / ACH', 'check': 'Check', 'cash': 'Cash', 'zelle': 'Zelle', 'other': 'Other'}})
        FormFieldSetting.objects.get_or_create(form_key="rent_ledger",field_key='reference',defaults={"label":'Payment Reference',"help_text":'Use a check number or transaction reference to help identify duplicates.',"option_labels":{}})
        FormFieldSetting.objects.get_or_create(form_key="rent_ledger",field_key='financial_account',defaults={"label":'Receiving Account',"help_text":'Optional for initial entry. Selecting an account does not change its bank balance.',"option_labels":{}})
        FormFieldSetting.objects.get_or_create(form_key="rent_ledger",field_key='reason',defaults={"label":'Reason',"help_text":'',"option_labels":{}})
        self.stdout.write(self.style.SUCCESS("Rent ledger settings initialized; existing wording preserved."))
